"""AQS-OPS-001 operating procedures per system: normal, start, stop, emergency (X-OPS-01, A-M-203). Built from AQS-COM-001 (systems
and units), AQS-COM-002 (start order), AQS-CTL-001 (loops), AQS-CTL-003 (trips) and the graph (liquid and gas inventories).
Stop is the reverse of start; emergency is the trip set of the system plus the plant ESD. Run after _startup.py."""
import csv, json, os, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
for k in ('OSHA_1910_119', 'IEC61511_2016', 'NFPA70E_2024'): cite(k)
C = list(csv.DictReader(open('docs-authority/inventory/COMMISSIONING.csv'))); SIF = list(csv.DictReader(open('docs-authority/sif_list.csv')))
sys_u = collections.defaultdict(list)
for r in C: sys_u[r['system']].append(r)
su = collections.defaultdict(list)
for s in SIF: su[s['unit']].append(s)
md = ['# Operating procedures', '', 'Document number: AQS-OPS-001', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-OPS-01. Generated by `docs-authority/_op_proc.py`. Study. A-M-203. Format per OSHA 1910.119(f): normal, start, stop, emergency; operating limits are the trip set points of AQS-CTL-003.', '',
      '## Plant-wide', '', '- **Plant ESD:** one push-button per level and at the control room. Trips every feed pump, heater and rectifier, closes the H2/O2/CO2 bank ESD valves, keeps ventilation, gas detection, fire pumps and the safety PLC on the ZnBr2 and backup generator.',
      '- **Power loss:** ZnBr2 carries the safety and life-support loads; backup generator auto-starts; process heaters shed first (AQS-ELS load shedding).',
      '- **Start order** AQS-COM-002; **stop order** is the reverse; process systems stop before utilities.', '']
order = list(dict.fromkeys(r['system'] for r in C)); n = len(order)
for i, s in enumerate(order, 1):
    rs = sys_u[s]; units = [r['unit'] for r in rs]; liq = [r['unit'] for r in rs if r['water_run_kg_d']]; trips = [x for u in units for x in su[u]]
    md += [f'## {i}. {s}', '', f'Units: {", ".join(units)}.', '',
           f'- **Normal:** {sum(int(r["loops"]) for r in rs)} loops on PLC-{s} in auto; operator rounds per shift on levels and temperatures of {", ".join(liq[:8]) or "the units"}{" …" if len(liq) > 8 else ""}; alarm response per AQS-CTL-001.',
           f'- **Start:** permissives: upstream systems 1-{i-1} running{" (none)" if i == 1 else ""}, trips healthy and reset, gas detection healthy. Fill liquid units, warm, then feed at 25/50/100 % with 1 h holds (AQS-COM-002 rates).',
           f'- **Stop:** feeds off, hold until temperature and gas inventories reach the hold state, isolate; downstream systems {i+1}-{n} stopped first{" (none)" if i == n else ""}. Normal stop leaves liquids in place, hot or cold standby.',
           f'- **Emergency:** {len(trips)} trips: ' + ('; '.join(f"{t['id']} {t['cause']} → {t['effect']}" for t in trips[:6]) + (' …' if len(trips) > 6 else '') if trips else 'plant ESD only') + '. After a trip: find cause, reset at the safety PLC (two-person), restart from Start.', '']
open('docs-authority/OPERATING_PROCEDURES.md', 'w').write('\n'.join(md) + '\n'); print(n)
